import{_ as a,c as t,o,ag as r}from"./chunks/framework.DZ_cNctr.js";const s="/docs/screenshots/ndpi-slide.webp",u=JSON.parse('{"title":"Hamamatsu NDPI Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Hamamatsu NanoZoomer NDPI slides in your browser, files over 4 GB too, from your disk or a link. Free, nothing to install.","frontmatter":{"title":"Hamamatsu NDPI Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Hamamatsu NanoZoomer NDPI slides in your browser, files over 4 GB too, from your disk or a link. Free, nothing to install."},"headers":[],"relativePath":"guides/hamamatsu-ndpi.md","filePath":"guides/hamamatsu-ndpi.md"}'),i={name:"guides/hamamatsu-ndpi.md"};function n(l,e,d,h,c,m){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="hamamatsu-ndpi-slides-in-the-browser" tabindex="-1">Hamamatsu NDPI Slides in the Browser <a class="header-anchor" href="#hamamatsu-ndpi-slides-in-the-browser" aria-label="Permalink to &quot;Hamamatsu NDPI Slides in the Browser&quot;">​</a></h1><p>Open the slides your Hamamatsu NanoZoomer saves, as they are. Nothing to convert, nothing to upload. A large slide starts showing right away, because the viewer reads only the part you look at.</p><p><img src="'+s+'" alt="CMU-2.ndpi open in the viewer, with its macro picture in the panel"></p><h2 id="how-it-opens" tabindex="-1">How It Opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How It Opens&quot;">​</a></h2><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on the viewer, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of slides</strong>, in Chrome and Edge. One slide opens, several show a list. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>The slide.</strong> Zoom from the whole slide down to single cells.</li><li><strong>Very large slides.</strong> Slides over 4 GB open.</li><li><strong>Colour profile.</strong> A slide that carries its scanner&#39;s colour profile is drawn with it. ICC in the RGB settings turns it off. See <a href="./channels.html#icc-colour-profile">Channels</a>.</li><li><strong>Macro.</strong> It appears under the title. Click it to enlarge it, and turn it if it arrives sideways. A label may show patient details. The viewer shows it and never saves or sends it.</li><li><strong>Z-stacks.</strong> The first plane opens, with a note.</li><li><strong>Pixel size and magnification.</strong> Both come from the slide, so measurements read in µm and the zoom bar shows the objective. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><h2 id="if-a-slide-does-not-open" tabindex="-1">If a Slide Does Not Open <a class="header-anchor" href="#if-a-slide-does-not-open" aria-label="Permalink to &quot;If a Slide Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>Fluorescence</td><td>This NDPI file is a fluorescence slide. The viewer cannot read it yet.</td></tr><tr><td>Another compression</td><td>This NDPI file uses a compression the viewer cannot read yet.</td></tr><tr><td>Not a Hamamatsu file</td><td>This file is not a Hamamatsu NDPI file.</td></tr><tr><td>A damaged or incomplete file</td><td>This NDPI file looks damaged or incomplete.</td></tr></tbody></table><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>Import GeoJSON, OME-XML or NDP.view <code>.ndpa</code> files, and export GeoJSON or OME-XML, from the <strong>Annotations</strong> panel. Send a link that opens the slide with its annotations. <a href="./annotation-exchange.html">Exchanging Annotations</a> shows how. To draw, measure and label shapes on the slide, see <a href="./annotations.html">Annotations</a>.</p><h2 id="public-slides-to-try" tabindex="-1">Public Slides to Try <a class="header-anchor" href="#public-slides-to-try" aria-label="Permalink to &quot;Public Slides to Try&quot;">​</a></h2><p><a href="https://openslide.org" target="_blank" rel="noreferrer">OpenSlide</a> shares test slides in its <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/Hamamatsu/" target="_blank" rel="noreferrer">Hamamatsu folder</a>. Download a slide, then drop it on the viewer. They are CC0.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a slide by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the slide and open it from your computer.</p><p>Addresses that start with <code>s3://</code> and <code>gs://</code> work too.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>CMU-2.ndpi</code> from the OpenSlide test data, CC0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The slide is read in your browser. Opening one counts as one opened image of the kind &quot;Hamamatsu NDPI file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',23)])])}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
